const data = $input.first().json;
const apiTestDone = data.apiTestDone === true;
const runTestDone = data.runTestDone === true;
let structuralScore = data.structuralScore || 0;
let structuralChecks = data.structuralChecks || data.checks || [];
let structuralIssues = data.structuralIssues || data.issues || [];
let apiScore = data.apiScore || 0;
let apiChecks = data.apiChecks || [];
let apiIssues = data.apiIssues || [];
let runScore = data.runScore || 0;
let runChecks = data.runChecks || [];
let runIssues = data.runIssues || [];
let templateName = data.templateName || 'Unknown';
let templateUrl = data.templateUrl || '';
let businessTask = data.businessTask || '';
let triggerType = data.triggerType || 'unknown';

// Пробрасываем workflowJson если он был передан на вход ← НОВАЯ СТРОКА
let workflowJson = data.workflowJson || $('Структурный анализ').first().json.workflowJson || null;

// === Итоговый score ===
let totalScore;
let testType;
if (runTestDone && apiTestDone) {
  // Все три уровня: структура 40% + API 35% + запуск 25%
  totalScore = Math.round(
    (structuralScore / 100) * 40 +
    (apiScore / 50) * 35 +
    (runScore / 30) * 25
  );
  testType = 'Полный тест: структура + API + запуск';
} else if (apiTestDone) {
  // Два уровня: структура 50% + API 50%
  totalScore = Math.round(
    (structuralScore / 100) * 50 +
    (apiScore / 50) * 50
  );
  testType = 'Структурный анализ + API-валидация';
} else {
  // Только структурный
  totalScore = structuralScore;
  testType = 'Только структурный анализ';
}
const passed = totalScore >= 60;

// === Все проверки вместе ===
const allChecks = [...structuralChecks];
if (apiChecks.length > 0) {
  allChecks.push('--- API-валидация ---');
  allChecks.push(...apiChecks);
}
if (runChecks.length > 0) {
  allChecks.push('--- Запуск ---');
  allChecks.push(...runChecks);
}
const allIssues = [...structuralIssues, ...apiIssues, ...runIssues];

// === Итоговое summary ===
let summary = '';
if (passed && runTestDone && runScore >= 20) {
  summary = 'Воркфлоу прошёл полную проверку: структура валидна, n8n принял, запуск успешен';
} else if (passed && runTestDone && runScore < 20) {
  summary = 'Структура и активация ОК, но запуск не вернул данные — возможны проблемы в логике';
} else if (passed && apiTestDone && apiScore >= 40) {
  summary = 'Воркфлоу прошёл проверку: структура валидна, n8n принял и активировал';
} else if (passed && apiTestDone) {
  summary = 'Структура хорошая, но n8n не смог активировать — возможны проблемы при запуске';
} else if (passed && !apiTestDone) {
  summary = 'Структура корректна, но полный тест невозможен (community ноды / Error Trigger)';
} else {
  summary = 'Воркфлоу не прошёл проверку: ' + (allIssues[0] || 'низкий score');
}

return [{
  json: {
    passed,
    score: totalScore,
    testType,
    summary,
    checks: allChecks,
    issues: allIssues,
    templateName,
    templateUrl,
    businessTask,
    triggerType,
    workflowJson  // ← НОВАЯ СТРОКА
  }
}];

const input = $input.first().json;
const wf = input.workflowJson;
const nodes = wf.nodes || [];
const connections = wf.connections || {};

// ===== 1. ДЕТЕКЦИЯ ТИПОВ НОД =====

const communityNodes = nodes.filter(n =>
  n.type &&
  !n.type.startsWith('n8n-nodes-base.') &&
  !n.type.startsWith('@n8n/n8n-nodes-langchain.') &&
  !n.type.startsWith('@n8n/')
);

const triggerNode = nodes.find(n =>
  n.type && (
    n.type.toLowerCase().includes('trigger') ||
    n.type.toLowerCase().includes('webhook')
  )
);

const isErrorTrigger = triggerNode &&
  triggerNode.type === 'n8n-nodes-base.errorTrigger';

const stickyNotes = nodes.filter(n =>
  n.type === 'n8n-nodes-base.stickyNote'
);

const workNodes = nodes.filter(n =>
  n.type !== 'n8n-nodes-base.stickyNote'
);

// ===== 2. ПРОВЕРКА CONNECTIONS =====

const connectedNodes = new Set();
Object.keys(connections).forEach(name => connectedNodes.add(name));
Object.values(connections).forEach(outputs => {
  if (outputs.main) {
    outputs.main.forEach(conns => {
      if (Array.isArray(conns)) {
        conns.forEach(c => connectedNodes.add(c.node));
      }
    });
  }
  ['ai_languageModel', 'ai_memory', 'ai_tool', 'ai_outputParser'].forEach(aiType => {
    if (outputs[aiType]) {
      outputs[aiType].forEach(conns => {
        if (Array.isArray(conns)) {
          conns.forEach(c => connectedNodes.add(c.node));
        }
      });
    }
  });
});

const orphanNodes = workNodes.filter(n => !connectedNodes.has(n.name));

const nodeNames = new Set(nodes.map(n => n.name));
const brokenConnections = [];
Object.entries(connections).forEach(([sourceName, outputs]) => {
  if (!nodeNames.has(sourceName)) {
    brokenConnections.push(`Источник "${sourceName}" не существует`);
  }
  Object.values(outputs).forEach(connArray => {
    if (Array.isArray(connArray)) {
      connArray.forEach(conns => {
        if (Array.isArray(conns)) {
          conns.forEach(c => {
            if (!nodeNames.has(c.node)) {
              brokenConnections.push(`Цель "${c.node}" не существует`);
            }
          });
        }
      });
    }
  });
});

// ===== 3. SCORE =====

let score = 0;
const checks = [];
const issues = [];

if (triggerNode) {
  score += 15;
  checks.push('✅ Триггер: ' + triggerNode.type.split('.').pop());
} else {
  issues.push('Нет триггер-ноды');
  checks.push('❌ Триггер не найден');
}

if (workNodes.length >= 2) {
  score += 10;
  checks.push('✅ Нод: ' + workNodes.length);
} else {
  issues.push('Слишком мало нод: ' + workNodes.length);
  checks.push('❌ Мало нод: ' + workNodes.length);
}

if (orphanNodes.length === 0) {
  score += 20;
  checks.push('✅ Все ноды подключены');
} else if (orphanNodes.length <= 2) {
  score += 10;
  const names = orphanNodes.map(n => n.name).join(', ');
  issues.push('Неподключённые ноды: ' + names);
  checks.push('⚠️ Неподключённых нод: ' + orphanNodes.length + ' (' + names + ')');
} else {
  issues.push('Много неподключённых нод: ' + orphanNodes.length);
  checks.push('❌ Неподключённых нод: ' + orphanNodes.length);
}

if (brokenConnections.length === 0) {
  score += 15;
  checks.push('✅ Все connections валидны');
} else {
  issues.push('Битые connections: ' + brokenConnections.join('; '));
  checks.push('❌ Битых connections: ' + brokenConnections.length);
}

if (communityNodes.length === 0) {
  score += 10;
  checks.push('✅ Только встроенные ноды');
} else {
  const names = communityNodes.map(n => n.name + ' (' + n.type + ')').join(', ');
  issues.push('Community ноды: ' + names);
  checks.push('⚠️ Community нод: ' + communityNodes.length + ' — ' + names);
}

if (!isErrorTrigger) {
  score += 5;
  checks.push('✅ Стандартный триггер');
} else {
  checks.push('⚠️ Error Trigger — запуск невозможен');
  issues.push('Error Trigger: невозможно протестировать запуском');
}

const needsAssembly = orphanNodes.length > 2 && stickyNotes.length > 0;
if (!needsAssembly) {
  score += 5;
  checks.push('✅ Воркфлоу собран');
} else {
  issues.push('Воркфлоу не собран — есть sticky notes и неподключённые ноды');
  checks.push('❌ Похоже на "сборочный набор" с инструкцией');
}

if (wf.settings && wf.settings.executionOrder === 'v1') {
  score += 5;
  checks.push('✅ executionOrder: v1');
} else {
  score += 2;
  checks.push('⚠️ executionOrder не задан (может работать)');
}

const connectionCount = Object.keys(connections).length;
if (connectionCount >= 1) {
  score += 10;
  checks.push('✅ Цепочки подключений: ' + connectionCount);
} else {
  issues.push('Нет ни одного подключения между нодами');
  checks.push('❌ Нет connections');
}

// ===== 4. МОЖНО ЛИ API-ТЕСТ? =====

const canApiTest = communityNodes.length === 0 &&
                   !isErrorTrigger &&
                   !needsAssembly &&
                   brokenConnections.length === 0 &&
                   triggerNode !== undefined;

// ===== 5. ОПРЕДЕЛЯЕМ ВНЕШНИЕ НОДЫ (ИНВЕРТИРОВАННАЯ ЛОГИКА) =====
// Белый список СЛУЖЕБНЫХ нод — всё остальное считается внешним и мокируется

const INTERNAL_PATTERNS = [
  'code', 'function', 'functionItem', 'set', 'if', 'switch',
  'merge', 'splitOut', 'splitInBatches', 'aggregate', 'limit',
  'filter', 'sort', 'removeDuplicates', 'summarize', 'compareDatasets',
  'dateTime', 'crypto', 'xml', 'html', 'markdown', 'convertToFile',
  'extractFromFile', 'compression', 'renameKeys', 'itemLists',
  'stickyNote', 'noOp', 'wait', 'respondToWebhook',
  'executeWorkflow', 'stopAndError', 'editFields',
  'start', 'manualTrigger', 'webhook', 'scheduleTrigger',
  'errorTrigger', 'executeWorkflowTrigger', 'chatTrigger',
  'formTrigger'
];

function isInternalNode(node) {
  const typeLower = node.type.toLowerCase();
  if (typeLower.includes('trigger')) return true;
  if (typeLower.includes('webhook')) return true;
  // AI sub-ноды не дают output в main — не мокируем
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.lm')) return true;
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.memory')) return true;
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.tool')) return true;
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.output')) return true;
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.embedding')) return true;
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.vector')) return true;
  // HTTP Request без credentials — публичный API, не мокируем
  if (typeLower.includes('httprequest')) {
    return !(node.credentials && Object.keys(node.credentials).length > 0);
  }
  return INTERNAL_PATTERNS.some(p => typeLower.includes(p.toLowerCase()));
}

const externalNodes = workNodes
  .filter(n => !isInternalNode(n))
  .map(n => ({ name: n.name, type: n.type }));

return [{
  json: {
    workflowJson: wf,
    businessTask: input.businessTask,
    templateName: input.templateName,
    templateUrl: input.templateUrl || '',
    structuralScore: score,
    maxStructuralScore: 100,
    checks,
    issues,
    canApiTest,
    communityNodesCount: communityNodes.length,
    communityNodesList: communityNodes.map(n => n.type),
    isErrorTrigger,
    needsAssembly,
    orphanCount: orphanNodes.length,
    totalWorkNodes: workNodes.length,
    triggerType: triggerNode ? triggerNode.type : 'none',
    hasStickyNotes: stickyNotes.length > 0,
    stickyContent: stickyNotes.map(n => n.parameters?.content || '').join('\n---\n'),
    externalNodes,                             // ← НОВОЕ
    externalNodesCount: externalNodes.length,  // ← НОВОЕ
  }
}];

const data = $input.first().json;
const wf = JSON.parse(JSON.stringify(data.workflowJson));
const webhookPath = 'test-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6);

for (let i = 0; i < wf.nodes.length; i++) {
  const n = wf.nodes[i];
  if (n.type && (
    n.type.toLowerCase().includes('trigger') ||
    n.type.toLowerCase().includes('webhook')
  )) {
    wf.nodes[i] = {
      id: n.id,
      name: n.name,
      type: 'n8n-nodes-base.webhook',
      typeVersion: 2,
      position: n.position,
      parameters: {
        httpMethod: 'POST',
        path: webhookPath,
        responseMode: 'lastNode'
      },
      webhookId: webhookPath
    };
    break;
  }
}

wf.nodes.forEach(n => {
  if (n.credentials) delete n.credentials;
});

const cleanWorkflow = {
  name: '[TEST] ' + (wf.name || 'Workflow') + ' ' + Date.now(),
  nodes: wf.nodes,
  connections: wf.connections || {},
  settings: {
    executionOrder: (wf.settings && wf.settings.executionOrder) || 'v1'
  }
};

return [{
  json: {
    workflow: cleanWorkflow,
    webhookPath,
    structuralScore: data.structuralScore,
    checks: data.checks,
    issues: data.issues,
    templateName: data.templateName,
    templateUrl: data.templateUrl,
    businessTask: data.businessTask,
    triggerType: data.triggerType,
    externalNodes: data.externalNodes,
    externalNodesCount: data.externalNodesCount,
  }
}];

