// === 1. Получаем данные ===
const apiPrepData = $('Подготовка к API-тесту').first().json;
const createResult = $('Создать воркфлоу').first().json;
const wf = JSON.parse(JSON.stringify(apiPrepData.workflow)); // deep clone

// === 2. Парсим ответ LLM ===
const raw = $input.first().json.text || $input.first().json.output || '';
let mocks = {};
let mockParseError = null;

try {
  let clean = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(clean);
  // LLM может вернуть { "mocks": {...} } или сразу { "НодаA": {...}, "НодаB": {...} }
  if (parsed.mocks && typeof parsed.mocks === 'object') {
    mocks = parsed.mocks;
  } else {
    const values = Object.values(parsed);
    if (values.length > 0 && typeof values[0] === 'object') {
      mocks = parsed;
    }
  }
} catch (e) {
  mockParseError = e.message;
  mocks = {};
}

// === 3. Логика мокирования (инвертированная) ===
const INTERNAL_PATTERNS = [
  'code', 'function', 'functionItem', 'set', 'if', 'switch',
  'merge', 'splitOut', 'splitInBatches', 'aggregate', 'limit',
  'filter', 'sort', 'removeDuplicates', 'summarize', 'compareDatasets',
  'dateTime', 'crypto', 'xml', 'html', 'markdown', 'convertToFile',
  'extractFromFile', 'compression', 'renameKeys', 'itemLists',
  'stickyNote', 'noOp', 'wait', 'respondToWebhook',
  'executeWorkflow', 'stopAndError', 'editFields',
  'start', 'manualTrigger', 'webhook', 'scheduleTrigger',
  'errorTrigger', 'executeWorkflowTrigger', 'chatTrigger',
  'formTrigger'
];

function shouldMock(node) {
  const typeLower = node.type.toLowerCase();
  // Триггеры и webhook уже заменены — не трогаем
  if (typeLower.includes('trigger')) return false;
  if (typeLower.includes('webhook')) return false;
  // AI sub-ноды не имеют main output — не мокируем
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.lm')) return false;
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.memory')) return false;
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.tool')) return false;
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.output')) return false;
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.embedding')) return false;
  if (node.type.startsWith('@n8n/n8n-nodes-langchain.vector')) return false;
  // HTTP Request: мокируем только если есть credentials
  // Без credentials — вероятно публичный API, пусть выполняется реально
  if (typeLower.includes('httprequest')) {
    return node.credentials && Object.keys(node.credentials).length > 0;
  }
  // Служебные ноды — не мокируем
  if (INTERNAL_PATTERNS.some(p => typeLower.includes(p.toLowerCase()))) return false;
  // Всё остальное — мокируем
  return true;
}

// === 4. Заменяем внешние ноды на Code-заглушки ===
const replacedNodes = [];

for (let i = 0; i < wf.nodes.length; i++) {
  const n = wf.nodes[i];
  if (shouldMock(n)) {
    const mockData = mocks[n.name] || {
      _mock: true,
      _originalType: n.type,
      success: true,
      data: 'mock'
    };
    // Имя ноды СОХРАНЯЕМ — connections привязаны к имени!
    wf.nodes[i] = {
      id: n.id,
      name: n.name,
      type: 'n8n-nodes-base.code',
      typeVersion: 2,
      position: n.position,
      parameters: {
        jsCode: 'return [{ json: ' + JSON.stringify(mockData) + ' }];'
      }
    };
    replacedNodes.push(n.name + ' (' + n.type.split('.').pop() + ')');
  }
}

// === 5. Зачищаем credentials ===
wf.nodes.forEach(n => {
  if (n.credentials) delete n.credentials;
});

return [{
  json: {
    workflow: wf,
    workflowId: createResult.id,
    webhookPath: apiPrepData.webhookPath,
    replacedNodes,
    mockCount: Object.keys(mocks).length,
    mockParseError,
    hasMocks: Object.keys(mocks).length > 0
  }
}];

const webhookResponse = $input.first().json;
const prepData = $('Парсинг и подготовка к запуску').first().json;
const apiPrepData = $('Подготовка к API-тесту').first().json;

let runScore = 0;
const runChecks = [];
const runIssues = [];

// Определяем: воркфлоу упал или нет
const isError = webhookResponse.error ||
                (webhookResponse.message && (
                  webhookResponse.message.toLowerCase().includes('error') ||
                  webhookResponse.message.toLowerCase().includes('not found') ||
                  webhookResponse.message.toLowerCase().includes('не найден')
                )) ||
                webhookResponse.code === 404 ||
                webhookResponse.statusCode === 404;

const hasData = webhookResponse &&
                typeof webhookResponse === 'object' &&
                Object.keys(webhookResponse).length > 0;

if (!isError && hasData) {
  const responseKeys = Object.keys(webhookResponse);
  runScore = 25;
  runChecks.push('✅ Запуск: воркфлоу отработал и вернул данные');
  // Бонус за содержательный ответ
  const hasRealData = responseKeys.some(k =>
    webhookResponse[k] !== null &&
    webhookResponse[k] !== undefined &&
    webhookResponse[k] !== '' &&
    k !== 'statusCode'
  );
  if (hasRealData) {
    runScore = 30;
    runChecks.push('✅ Ответ содержит данные: ' + responseKeys.slice(0, 5).join(', '));
  }
} else {
  const errMsg = webhookResponse?.message ||
                 webhookResponse?.error ||
                 JSON.stringify(webhookResponse).substring(0, 100);
  runIssues.push('Запуск не удался: ' + errMsg);
  runChecks.push('❌ Запуск: воркфлоу не вернул данные');
  runChecks.push('   Ответ: ' + String(errMsg).substring(0, 80));
}

// Инфо о замокированных нодах
if (prepData.replacedNodes && prepData.replacedNodes.length > 0) {
  runChecks.push('ℹ️ Замокировано нод: ' + prepData.replacedNodes.length);
  prepData.replacedNodes.forEach(n => runChecks.push('   🔸 ' + n));
}

if (prepData.mockParseError) {
  runChecks.push('⚠️ Ошибка парсинга моков LLM: ' + prepData.mockParseError);
  runChecks.push('   Использованы дефолтные заглушки');
}

return [{
  json: {
    runScore,
    runChecks,
    runIssues,
    runTestDone: true,
    structuralScore: apiPrepData.structuralScore,
    structuralChecks: apiPrepData.checks,
    structuralIssues: apiPrepData.issues,
    templateName: apiPrepData.templateName,
    templateUrl: apiPrepData.templateUrl,
    businessTask: apiPrepData.businessTask,
    triggerType: apiPrepData.triggerType,
    workflowId: prepData.workflowId,
    apiTestDone: true
  }
}];

const activateResult = $input.first().json;
const apiPrepData = $('Подготовка к API-тесту').first().json;
const createResult = $('Создать воркфлоу').first().json;

const apiChecks = [];
const apiIssues = [];
let apiScore = 0;

// Создание прошло?
if (createResult.id) {
  apiScore += 20;
  apiChecks.push('✅ API: воркфлоу создан (id: ' + createResult.id + ')');
} else {
  const err = createResult.message || JSON.stringify(createResult).substring(0, 100);
  apiIssues.push('API не принял воркфлоу: ' + err);
  apiChecks.push('❌ API: ошибка создания — ' + err);
}

// Активация не прошла
const errMsg = activateResult.message ||
               activateResult.error ||
               JSON.stringify(activateResult).substring(0, 150);
apiIssues.push('Активация не прошла: ' + errMsg);
apiChecks.push('❌ API: ошибка активации — ' + errMsg);
apiScore += 5; // Частичный балл — создался, но не активировался

return [{
  json: {
    runScore: 0,
    runChecks: [],
    runIssues: [],
    runTestDone: false,
    apiScore,
    apiChecks,
    apiIssues,
    structuralScore: apiPrepData.structuralScore,
    structuralChecks: apiPrepData.checks,
    structuralIssues: apiPrepData.issues,
    templateName: apiPrepData.templateName,
    templateUrl: apiPrepData.templateUrl,
    businessTask: apiPrepData.businessTask,
    triggerType: apiPrepData.triggerType,
    workflowId: createResult.id,
    apiTestDone: true
  }
}];

// Берём данные из той ноды оценки, которая реально отработала
let evalData;

try {
  evalData = $('Оценка запуска').first().json;
} catch(e) {
  try {
    evalData = $('Оценка без запуска').first().json;
  } catch(e2) {
    evalData = $input.first().json;
  }
}

// API score:
// Если запуск был (Level 3) — значит создание + активация точно прошли → 50 баллов
// Если не было — берём из "Оценка без запуска"
let apiScore = 0;
let apiChecks = [];
let apiIssues = [];

if (evalData.runTestDone) {
  apiScore = 50; // 20 создание + 30 активация
  apiChecks = [
    '✅ API: воркфлоу создан',
    '✅ API: воркфлоу активирован — все ноды валидны'
  ];
} else if (evalData.apiScore !== undefined) {
  apiScore = evalData.apiScore;
  apiChecks = evalData.apiChecks || [];
  apiIssues = evalData.apiIssues || [];
}

return [{
  json: {
    structuralScore: evalData.structuralScore || 0,
    structuralChecks: evalData.structuralChecks || [],
    structuralIssues: evalData.structuralIssues || [],
    apiScore,
    apiChecks,
    apiIssues,
    runScore: evalData.runScore || 0,
    runChecks: evalData.runChecks || [],
    runIssues: evalData.runIssues || [],
    runTestDone: evalData.runTestDone || false,
    apiTestDone: true,
    templateName: evalData.templateName || 'Unknown',
    templateUrl: evalData.templateUrl || '',
    businessTask: evalData.businessTask || '',
    triggerType: evalData.triggerType || 'unknown'
  }
}];
